<div class="top"><h1>Demandes de devis</h1></div>
<form class="filters-bar" method="get"><input name="q" placeholder="Réf., nom, e-mail, tél." value="<?= e(get('q')) ?>"><select name="status"><option value="">Tous les statuts</option><?= select_opts(array_map(fn($s) => $s[0], QUOTE_STATUS), get('status')) ?></select><button class="btn btn-p btn-sm">Filtrer</button></form>
<div class="tbl-wrap"><table class="tbl"><thead><tr><th>N°</th><th>Date</th><th>Client</th><th>Statut</th><th class="right">Montant</th></tr></thead><tbody><?php foreach ($rows as $q): ?><tr><td><a href="/admin/devis/<?= (int) $q['id'] ?>"><b><?= e($q['ref']) ?></b></a></td><td><?= fdate($q['created_at'], true) ?></td><td><?= e($q['name']) ?><br><small class="muted"><?= e($q['phone'] ?: $q['email']) ?></small></td><td><?= status_badge(QUOTE_STATUS, $q['status']) ?></td><td class="right"><?= $q['total'] ? money($q['total']) : '—' ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="center muted">Aucune demande.</td></tr><?php endif; ?></tbody></table></div>
